CREATE procedure [dbo].[ecf_comprobante_recibido_selectByEmisorId]  
 @emisorId uniqueidentifier,  
 @desde datetime,  
 @hasta datetime  
as  
 declare @rncComprador varchar(20)  
 select @rncComprador = rnc from ecf_emisor where Id = @emisorId   
  
 select * from ecf_comprobante_recibido where DocumentoIdentidad = @rncComprador and FechaRecibido between @desde and @hasta

create procedure [dbo].[ecf_comprobante_selectStatus]
 @emisorId uniqueidentifier,
 @ncf varchar(20)
as  
 select Id, Ncf, StatusEcf, Referencia, TipoNcf, TrackId, CodigoSeguridadEcf, convert(decimal(19,2), Total) as MontoTotal,
		RncEmisor, EmisorId 
 from ecf_comprobante with (NOLOCK)       
 where EmisorId = @emisorId and Ncf = @ncf
 and StatusEcf <> 'CANCELADO'

create procedure [dbo].[ecf_session_post] 
 @emisorId uniqueidentifier,
 @token nvarchar(2000),
 @vencimiento datetime
as
 insert into ecf_session (EmisorId, Token, FechaRegsitro, Cancelada, Expiracion)
 values (@emisorId, @token, GETDATE(), 0, @vencimiento)

CREATE procedure [dbo].[ecf_comprobante_create]  
 @id int,  
 @ncf varchar(20),  
 @fecha datetime,  
 @tipoNcf varchar(2),  
 @rnc varchar(20),  
 @razonSocial varchar(100),   
 @ValorGravado decimal(19,2),  
 @valorExento decimal(19,2),  
 @itbis decimal(19,2),  
 @concepto varchar(200),  
 @tipoIngreso varchar(16),   
 @nuId int output,  
 @ncfModificado varchar(20) = null,  
 @fechaNcfModificado datetime = null,  
 @fechaVenceNcf datetime = null,  
 @codSeg varchar(20) = null,  
 @TrackId varchar(50) = null  
as  
 if @id = 0 begin   
     
   if isnull(@ncf,'') = '' begin  
     exec svCompFiscal2025 @tipoNcf,@ncf output, @fechaVenceNcf output   
   end  
  
   insert into ecf_comprobante  
 (Referencia, Fecha, TipoNcf, DocumentoIdentidad, RazonSocialComprador, SubTotal1,   
  SubTotal3, MontoItbis1, TipoIngresos, NcfModificado, FechaNcfModificado,   
  CodigoSeguridadEcf, TrackId, VencimientoNcf, Ncf,Itbis1,Itbis2,Itbis3)  
  select newid(),   
    @fecha,   
    @tipoNcf,     
    @rnc,   
    @razonSocial,  
    @ValorGravado,  
    @valorExento,  
    @itbis,      
    @tipoIngreso,  
    @ncfModificado,  
    @fechaNcfModificado,  
    @codSeg,  
    @TrackId,  
    @fechaVenceNcf,  
    @ncf,
	case when @ValorGravado > 0 then '18' else '' end,
	'',
	''
  
   set @nuId = SCOPE_IDENTITY()  
   return @@error  
 end  
  
 update ecf_comprobante  
   set DocumentoIdentidad = @rnc, Fecha = @fecha,   
   TipoIngresos = @tipoIngreso,  
   TipoNcf = @tipoNcf,  
   RazonSocialComprador = @razonSocial,  
   SubTotal1 = @ValorGravado,  
   SubTotal3 = @valorExento,  
   MontoItbis1 = @itbis,  
   NcfModificado = isnull(@ncfModificado, NcfModificado),  
   VencimientoNcf = isnull(@fechaVenceNcf,VencimientoNcf),  
   Ncf = isnull(@ncf, Ncf),  
   CodigoSeguridadEcf = isnull(@codSeg, CodigoSeguridadEcf),  
   TrackId = isnull(@trackId, TrackId) ,
   Itbis1 = case when @ValorGravado > 0 then '18' else '' end
 where Id = @id   
 set @nuId = @id   
  
return @@error

CREATE procedure [dbo].[ecf_comprobante_det_post] 
 @id int, 
 @comprobanteId int,
 @productoId varchar(30),
 @nombreProducto varchar(70), 
 @descripcion varchar(70), 
 @unidad varchar(2), 
 @cantidad decimal(19,2), 
 @precio decimal(19,2), 
 @indicadorFacturacion varchar(2), 
 @itbis decimal(19,2), 
 @descuento decimal(19,2),  
 @montoSubDescuento1 decimal(19,2),
 @montoSubDescuento2 decimal(19,2),
 @tipoSubDescuento1 varchar(2),
 @TipoSubDescuento2 varchar(2),
 @montoSubRecargo decimal(19,2),
 @tipoSubRecargo varchar(2),
 @porcSubRecargo decimal(19,2),
 @isrRetenidoItem decimal(19,2) = 0, 
 @itbisRetenidoItem decimal(19,2) = 0, 
 @tasaDeCambio decimal(19,2) = 1, 
 @ReferenciaId uniqueidentifier = null,
 @indicadorBienOServicio varchar(2) = '2'
as
 --declare @indicadorFacturacion varchar(2)

 --if @itbis1 > 0 
 --  set @indicadorFacturacion = '1'
 --else if @itbis2 > 0 
 --  set @indicadorFacturacion = '2'
 -- else 
 --  set @indicadorFacturacion = '4'

 if @indicadorBienOServicio is null 
   set @indicadorBienOServicio = '2'

 if exists (select 1 from ecf_comprobante_detalle where Id = @id) begin
   update ecf_comprobante_detalle
     set ProductoId = @productoId,
		 NombreProducto = @nombreProducto,
		 Descripcion = @descripcion,
		 Unidad = @unidad,
		 Cantidad = @cantidad,
		 Precio = @precio * @tasaDeCambio,
		 Itbis = @itbis * @tasaDeCambio,
		 Descuento = @descuento * @tasaDeCambio,
		 IndicadorBienOServicio = @indicadorBienOServicio,
		 IndicadorFacturacion = @indicadorFacturacion,
		 IsrRetenidoItem = @isrRetenidoItem * @tasaDeCambio,
		 ItbisRetenidoItem = @itbisRetenidoItem * @tasaDeCambio,
		 ReferenciaId = @ReferenciaId,
		 MontoSubDescuento1 = @montoSubDescuento1 * @tasaDeCambio,
		 MontoSubDescuento2 = @montoSubDescuento2 * @tasaDeCambio,
		 TipoSubDescuento1 = @tipoSubDescuento1,
		 TipoSubDescuento2 = @TipoSubDescuento2,
		 MontoSubRecargo1 = @montoSubRecargo * @tasaDeCambio,
		 TipoSubRecargo1 = @tipoSubRecargo,
		 PorcientoSubRecargo1 = @porcSubRecargo
	where Id = @id
 end
 else begin 
   insert into ecf_comprobante_detalle
    (ReferenciaId,ComprobanteId,ProductoId,NombreProducto,Descripcion,Unidad,Cantidad,
     Precio,Itbis,Descuento, IndicadorBienOServicio,IndicadorFacturacion,IsrRetenidoItem,
	 ItbisRetenidoItem, MontoSubDescuento1, MontoSubDescuento2, MontoSubRecargo1, 
	 TipoSubDescuento1, TipoSubDescuento2, TipoSubRecargo1, PorcientoSubRecargo1)
   values 
	(@referenciaId,@comprobanteId,@productoId,@nombreProducto,@descripcion,@unidad,@cantidad,
     @precio * @tasaDeCambio,@itbis * @tasaDeCambio,@descuento * @tasaDeCambio, @indicadorBienOServicio,
	 @indicadorFacturacion,@isrRetenidoItem * @tasaDeCambio,
	 @itbisRetenidoItem * @tasaDeCambio, @montoSubDescuento1 * @tasaDeCambio, @montoSubDescuento2 * @tasaDeCambio,
	 @montoSubRecargo * @tasaDeCambio, @tipoSubDescuento1, @TipoSubDescuento2, @tipoSubRecargo, @porcSubRecargo)
 end

 return @@error

  
  
CREATE   PROCEDURE [dbo].[ecf_comprobante_post]  
    @emisorId uniqueidentifier,
	@rncEmisor varchar(20), 
    @id int,   
    @Referencia UNIQUEIDENTIFIER,  
    @Fecha DATETIME,  
    @Numero NVARCHAR(50),  
    @TipoNcf NVARCHAR(2),  
    @DocumentoIdentidad NVARCHAR(20),      
    @Sucursal NVARCHAR(50),  
    @RazonSocialComprador NVARCHAR(255),      
    @TipoIngresos NVARCHAR(2) = NULL,  
    @SubTotal1 DECIMAL(18, 2),  
	@SubTotal2 decimal(18,2),
    @exento DECIMAL(18, 2),      
    @MontoItbis1 DECIMAL(18, 2),  
	@MontoItbis2 decimal(18,2),
    @MontoDescuento DECIMAL(18, 2),  
    @MontoRecargo DECIMAL(18, 2),              
    @EmailComprador NVARCHAR(255),  
    @CompradorId NVARCHAR(50),  
    @ContactoComprador NVARCHAR(100),      
    @DireccionComprador NVARCHAR(500),  
    @PedidoNumero NVARCHAR(50),  
    @NumeroOrdenCompra NVARCHAR(50),          
    @MunicipioCliente NVARCHAR(100) = '',  
    @ProvinciaCliente NVARCHAR(100) = '',              
    @Moneda NVARCHAR(3) = 'DOP',  
    @TasaCambio DECIMAL(18, 4) = 1,  
    @SubTotalOtraMoneda DECIMAL(18, 2) = 0,  
	@ncf varchar(20) = '',  
	@fechaVenceNcf datetime = null,   
	@ncfModificado varchar(20) = '',  
	@fechaNcfModificado datetime = null,	
	@itbisRetenido decimal(19,2) = 0,
	@IsrRetenido decimal(19,2) = 0, 
	@indNotaCredito varchar(16) = '',
		
	@newId int output   
AS  
BEGIN  
  SET NOCOUNT ON;  
  declare @itbis1 varchar(2) = '', @itbis2 varchar(2) = '', @itbis3 varchar(2) = '', @tipoDocidentidad char(1) = ''  
  if isnull(@id,0) = 0 begin  
    select @id = id from ecf_comprobante where Referencia = @Referencia  
  end  
  
  if @MontoItbis1 > 0   
    set @itbis1 = '18'  
  if @MontoItbis2 > 0 
    set @itbis2 = '16'
  
  set @documentoIdentidad = replace(ltrim(rtrim(@DocumentoIdentidad)),'-','')  
  
  set @TipoDocIdentidad = case len(@DocumentoIdentidad)   
    when '11' then '1'  
	when '9' then '2'  
	else ''  
  end
  
  if not exists (select 1 from ecf_emisor where Id = @emisorId and SubscripcionTipo = 'CLIENTE') begin
    raiserror('El emisor especificado no existe o esta inactivo',16,7)
	return -2
  end
  
  if isnull(@id,0) = 0 begin   
      
  if exists (select 1 from ecf_comprobante where EmisorId = @emisorId and Ncf = @ncf) begin 
    raiserror ('Ya existe ese ncf para este emisor',16,6)
	return -1
  end
 --if isnull(@ncf,'') = ''  begin  
 --  exec svCompFiscal2025 @tipoNcf, @ncf output, @fechaVenceNcf output    
 --end   
  
    INSERT INTO ecf_comprobante (  
        Referencia,  
        Fecha,  
        Numero,          
        TipoNcf,  
        DocumentoIdentidad,          
        Sucursal,  
        RazonSocialComprador,          
        TipoIngresos,  
        SubTotal1, 		
		subtotal2,
        SubTotal3,              
        MontoItbis1,  
		MontoItbis2,
        MontoDescuento,  
        MontoRecargo,           
        StatusEcf,  
        EmailComprador,  
        CompradorId,  
        ContactoComprador,          
        DireccionComprador,  
        PedidoNumero,  
        NumeroOrdenCompra,  
        IndicadorMontoGravado,          
        MunicipioCliente,  
        ProvinciaCliente,                  
        FormaPago,          
        Moneda,  
        TasaCambio,  
		Ncf,  
		VencimientoNcf,  
		NcfModificado,  
		FechaNcfModificado,  
		TipoDocIdentidad,  
		Itbis1,  
		Itbis2,  
		Itbis3,
		IndNotaCredito,		  
		ItbisRetenido,
		IsrRetenido,
		EmisorId,
		RncEmisor
    ) VALUES (  
        @Referencia,  
        @Fecha,  
        @Numero,          
        @TipoNcf,  
        @DocumentoIdentidad,          
        @Sucursal,  
        @RazonSocialComprador,          
        @TipoIngresos,  
        @SubTotal1 * @TasaCambio, 
		@SubTotal2 * @TasaCambio,
        @exento * @TasaCambio,  
        @MontoItbis1 * @TasaCambio,
		@MontoItbis2 * @TasaCambio,
        @MontoDescuento * @TasaCambio,  
        @MontoRecargo * @TasaCambio,         
		'PENDIENTE',  
        @EmailComprador,  
        @CompradorId,  
        @ContactoComprador,          
        @DireccionComprador,  
        @PedidoNumero,  
        @NumeroOrdenCompra,  
        '0',          
        @MunicipioCliente,  
        @ProvinciaCliente,      
		'1',  
        @Moneda,  
        @TasaCambio,  
		@ncf,   
		@fechaVenceNcf,  
		@NcfModificado,  
		@FechaNcfModificado,  
		@TipoDocIdentidad,  
		@itbis1,  
		@itbis2,  
		@itbis3,
		@indNotaCredito,
		@itbisRetenido * @TasaCambio,
		@isrRetenido * @TasaCambio, 
		@emisorId,
		@rncEmisor
    );  
   
    set @newId = SCOPE_IDENTITY();  
 return   
  end  
  
  update ecf_comprobante  
    set Referencia = @referencia,  
        Fecha = @fecha,  
        Numero = @numero,          
        TipoNcf = @TipoNcf,  
        DocumentoIdentidad = @DocumentoIdentidad,          
        Sucursal = @Sucursal,  
        RazonSocialComprador = @RazonSocialComprador,          
        TipoIngresos = @TipoIngresos,  
        SubTotal1 = @SubTotal1 * @TasaCambio,     
		SubTotal2 = @SubTotal2 * @TasaCambio,
        SubTotal3 = @exento * @TasaCambio,          
        MontoItbis1 = @MontoItbis1 * @TasaCambio,
		MontoItbis2 = @MontoItbis2 * @TasaCambio,
        MontoDescuento = @MontoDescuento * @TasaCambio,  
        MontoRecargo = @MontoRecargo * @TasaCambio,                   
        EmailComprador = @EmailComprador,  
        CompradorId = @CompradorId,  
        ContactoComprador = @ContactoComprador,          
        DireccionComprador = @DireccionComprador,  
        PedidoNumero = @PedidoNumero,  
        NumeroOrdenCompra = @NumeroOrdenCompra,          
        MunicipioCliente = @MunicipioCliente,  
        ProvinciaCliente = @ProvinciaCliente,                          
        Moneda = @Moneda,  
        TasaCambio = @TasaCambio,  
  NcfModificado = @ncfModificado,  
  FechaNcfModificado = @fechaNcfModificado,  
  TipoDocIdentidad = @TipoDocIdentidad,  
  Itbis1 = @itbis1,  
  Itbis2 = @itbis2,  
  Itbis3 = @itbis3,
  IndNotaCredito = @indNotaCredito,
  RncEmisor = @rncEmisor,
  EmisorId = @emisorId,
  IsrRetenido = @IsrRetenido * @TasaCambio,
  ItbisRetenido = @itbisRetenido * @TasaCambio
  where Id = @id   
  
 set @newid = @id   
   
END

